
CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "firstName" TEXT NOT NULL,
  "lastName" TEXT NOT NULL,
  "address" TEXT NOT NULL,
  "email" TEXT UNIQUE NOT NULL,
  "password" TEXT NOT NULL,
  "created_at" TIMESTAMP DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "books" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "bookName" TEXT NOT NULL,
  "userId" INTEGER NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending', 'processing', 'completed', 'failed')),
  "uploadedDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE("bookName", "userId")
);

CREATE TABLE "bookJob" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "bookId" INTEGER NOT NULL REFERENCES "books"("id") ON DELETE CASCADE,
  "status" TEXT NOT NULL DEFAULT 'queued' CHECK ("status" IN ('queued', 'processing', 'completed', 'failed')),
  "errorMessage" TEXT,
  "createdAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "startedAt" TIMESTAMP,
  "completedAt" TIMESTAMP
);


CREATE TABLE "conversation" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "userQuestion" TEXT NOT NULL,
  "chatResponse" TEXT NOT NULL,
  "userId" INTEGER NOT NULL,
  "bookId" INTEGER NOT NULL,
  "conversationTime" TIMESTAMP DEFAULT (CURRENT_TIMESTAMP)
);


ALTER TABLE "books" ADD FOREIGN KEY ("userId") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "conversation" ADD FOREIGN KEY ("userId") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "conversation" ADD FOREIGN KEY ("bookId") REFERENCES "books" ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "bookJob" ADD FOREIGN KEY ("bookId") REFERENCES "books" ("id") DEFERRABLE INITIALLY IMMEDIATE;